SET NOCOUNT ON;
SELECT
 JSON_QUERY((SELECT name,collation_name,is_read_committed_snapshot_on,snapshot_isolation_state_desc,recovery_model_desc,page_verify_option_desc,is_auto_close_on FROM sys.databases WHERE database_id=DB_ID() FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)) AS settings,
 JSON_QUERY((SELECT t.name AS [table],c.name,ty.name AS [type],c.max_length,c.precision,c.scale,c.is_nullable,c.is_identity,d.name AS default_name,d.definition AS default_sql FROM sys.tables t JOIN sys.columns c ON c.object_id=t.object_id JOIN sys.types ty ON ty.user_type_id=c.user_type_id LEFT JOIN sys.default_constraints d ON d.object_id=c.default_object_id WHERE t.is_ms_shipped=0 ORDER BY t.name,c.column_id FOR JSON PATH)) AS columns,
 JSON_QUERY((SELECT t.name AS [table],i.name,i.is_unique,i.is_primary_key,i.filter_definition,JSON_QUERY((SELECT c.name,ic.is_descending_key,ic.is_included_column FROM sys.index_columns ic JOIN sys.columns c ON c.object_id=ic.object_id AND c.column_id=ic.column_id WHERE ic.object_id=i.object_id AND ic.index_id=i.index_id ORDER BY ic.is_included_column,ic.key_ordinal,ic.index_column_id FOR JSON PATH)) AS columns FROM sys.tables t JOIN sys.indexes i ON i.object_id=t.object_id WHERE t.is_ms_shipped=0 AND i.index_id>0 ORDER BY t.name,i.name FOR JSON PATH)) AS indexes,
 JSON_QUERY((SELECT name,OBJECT_NAME(parent_object_id) AS [table],definition,is_disabled,is_not_trusted FROM sys.check_constraints FOR JSON PATH)) AS checks,
 JSON_QUERY((SELECT f.name,OBJECT_NAME(f.parent_object_id) AS [table],f.delete_referential_action_desc,f.update_referential_action_desc,f.is_disabled,f.is_not_trusted,JSON_QUERY((SELECT COL_NAME(c.parent_object_id,c.parent_column_id) AS [column],OBJECT_NAME(c.referenced_object_id) AS reference_table,COL_NAME(c.referenced_object_id,c.referenced_column_id) AS reference_column FROM sys.foreign_key_columns c WHERE c.constraint_object_id=f.object_id ORDER BY c.constraint_column_id FOR JSON PATH)) AS columns FROM sys.foreign_keys f FOR JSON PATH)) AS foreignKeys,
 JSON_QUERY((SELECT v.name,m.definition FROM sys.views v JOIN sys.sql_modules m ON m.object_id=v.object_id WHERE v.is_ms_shipped=0 FOR JSON PATH)) AS views
FOR JSON PATH,WITHOUT_ARRAY_WRAPPER;
